            if ((arr[i] + arr[j]) % k == 0 && !sums.contains(arr[i] + arr[j])) {
                sums.add(arr[i] + arr[j]);
            }
        }
    }

    // Check if there are n/2 pairs with the required property
    return sums.size() == arr.length / 2;
}

