    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int average = sum / nums.length;

    int leftSum = 0;
    for (int i = 0; i < nums.length / 2; i++) {
        leftSum += nums[i];
        if (leftSum == average) {
            return true;
        }
    }

    int rightSum = sum - leftSum;
    for (int i = nums.length / 2; i < nums.length; i++) {
        rightSum -= nums[i];
        if (rightSum == average) {
            return true;
        }
    }

    return false;
}

